<script setup lang="ts">
import { computed } from 'vue'
const props=defineProps<{employee:any;cutoff:any}>()
const money=(value:number)=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP'}).format(Number(value||0))
const date=(value:string)=>new Date(value+'T00:00:00').toLocaleDateString('en-PH',{month:'short',day:'numeric',year:'numeric'})
const period=(value:any)=>date(value.periodStart)+' – '+date(value.periodEnd)
const displayNumber=(employee:any)=>employee.EmployeeNumber?.trim()||'EMP-'+String(employee.EmployeeID).padStart(4,'0')
const lines=(section:string)=>props.cutoff.lines.filter((line:any)=>line.section===section)
const governmentTotal=computed(()=>lines('government').reduce((sum:number,line:any)=>sum+Number(line.amount),0))
const otherTotal=computed(()=>lines('other').reduce((sum:number,line:any)=>sum+Number(line.amount),0))
</script>
<template>
              <article class="payslip-sheet" aria-label="Finalized payslip">
              <header class="sheet-head"><div><p class="eyebrow">PAYSLIP · {{ cutoff.status.toUpperCase() }}</p><h3>{{ employee.AgencyName || 'Payroll' }}</h3><p>{{ employee.EmployeeName }} · {{ displayNumber(employee) }}</p></div><div class="sheet-period"><span>PAYROLL CUTOFF</span><strong>{{ period(cutoff) }}</strong><small>{{ cutoff.payrollIds.length }} payroll record{{ cutoff.payrollIds.length === 1 ? '' : 's' }}</small></div></header>
              <div class="sheet-meta" :class="{ 'sheet-meta-reliever': cutoff.assignmentType === 'Reliever' }"><div><span>Employee</span><strong>{{ employee.EmployeeName }}</strong></div><div><span>Position</span><strong>{{ employee.PositionName || 'Unassigned' }}</strong></div><div><span>{{ cutoff.assignmentType === 'Reliever' ? 'Site' : 'Sites in this cutoff' }}</span><strong>{{ cutoff.assignmentType === 'Reliever' ? cutoff.siteName : cutoff.sources.length }}</strong></div><div v-if="cutoff.assignmentType === 'Reliever'"><span>Shift type</span><strong>Reliever</strong></div></div>
              <div class="sheet-columns">
                <section class="sheet-section"><h4>Gross income</h4><div class="line-head"><span>Pay item</span><span>Hours</span><span>Amount</span></div><div v-for="line in lines('earnings')" :key="`earning-${line.label}`" class="sheet-line"><span>{{ line.label }}</span><span>{{ line.hours ? line.hours.toFixed(2) : '—' }}</span><strong>{{ money(line.amount) }}</strong></div><div v-if="lines('adjustment').length" class="subheading">Payroll adjustments</div><div v-for="line in lines('adjustment')" :key="`adjustment-${line.label}`" class="sheet-line"><span>{{ line.label.replace(/^Adjustment · /, '') }}</span><span>{{ line.hours ? line.hours.toFixed(2) : '—' }}</span><strong>{{ money(line.amount) }}</strong></div><p v-if="!lines('earnings').length && !lines('adjustment').length" class="empty-line">No earning lines.</p><div class="section-total"><span>Total gross income</span><strong>{{ money(cutoff.gross) }}</strong></div></section>
                <section class="sheet-section"><h4>Government deductions</h4><div class="line-head two"><span>Item</span><span>Amount</span></div><div v-for="line in lines('government')" :key="`government-${line.label}`" class="sheet-line two"><span>{{ line.label }}</span><strong>{{ money(line.amount) }}</strong></div><p v-if="!lines('government').length" class="empty-line">No government deductions.</p><div class="section-total"><span>Government total</span><strong>{{ money(governmentTotal) }}</strong></div></section>
                <section class="sheet-section"><h4>Other deductions</h4><div class="line-head two"><span>Item</span><span>Amount</span></div><div v-for="line in lines('other')" :key="`other-${line.label}`" class="sheet-line two"><span>{{ line.label }}</span><strong>{{ money(line.amount) }}</strong></div><p v-if="!lines('other').length" class="empty-line">No other deductions.</p><div class="section-total"><span>Other total</span><strong>{{ money(otherTotal) }}</strong></div></section>
              </div>
              <div class="sheet-footer"><div><span>Total deductions</span><strong>{{ money(cutoff.deductions) }}</strong></div><div class="net-pay"><span>Net pay</span><strong>{{ money(cutoff.net) }}</strong></div></div>
              <div class="source-block"><h4>{{ cutoff.assignmentType === 'Reliever' ? 'Payroll sources at this site' : 'Payroll sources in this cutoff' }}</h4><p v-if="cutoff.sources.length > 1">Combined from {{ cutoff.sources.length }} {{ cutoff.assignmentType === 'Reliever' ? 'payroll records' : 'site payrolls' }}. Each source remains listed below for review.</p><div v-for="source in cutoff.sources" :key="source.payrollId" class="source-row"><div><strong>{{ source.siteName }}</strong><small>{{ source.clientName }}{{ source.batchId ? ` · DTR-${String(source.batchId).padStart(4, '0')}` : '' }}</small></div><span>{{ money(source.gross) }} gross</span><span>{{ money(source.net) }} net</span></div></div>
              <p class="sheet-note">Amounts come from finalized payroll records. Cancelled payroll is excluded from this history.</p>
              </article>
</template>
<style scoped>
.payslip-sheet{--ink:#112b53;--muted:#657d9f;--line:#d5e1f2;color:var(--ink);border:1px solid var(--line);border-radius:14px;background:#fff;overflow:hidden}.eyebrow{margin:0;color:#2863db;font-size:.72rem;font-weight:800;letter-spacing:.08em}.sheet-head{display:flex;justify-content:space-between;gap:20px;background:#f0f5ff;border-bottom:1px solid var(--line);padding:24px 26px}.sheet-head h3{margin:6px 0;font-size:1.3rem}.sheet-head p:not(.eyebrow){margin:0;color:var(--muted);font-size:.83rem}.sheet-period{text-align:right;display:grid;gap:4px}.sheet-period span,.sheet-meta span{color:var(--muted);font-size:.68rem;text-transform:uppercase;font-weight:750}.sheet-period strong{font-size:.87rem}.sheet-period small{color:var(--muted)}.sheet-meta{display:grid;grid-template-columns:1.5fr 1fr .6fr;gap:14px;padding:16px 26px;border-bottom:1px solid var(--line)}.sheet-meta-reliever{grid-template-columns:1.5fr 1fr 1fr .8fr}.sheet-meta div{display:grid;gap:4px}.sheet-meta strong{font-size:.82rem}.sheet-columns{display:grid;grid-template-columns:1.3fr 1fr 1fr}.sheet-section{min-width:0;padding:22px 24px;border-right:1px solid var(--line);display:flex;flex-direction:column}.sheet-section:last-child{border-right:0}.sheet-section h4{margin:0 0 12px;color:#17417c;font-size:.91rem;text-transform:uppercase}.line-head,.sheet-line{display:grid;grid-template-columns:minmax(0,1fr) 62px 104px;align-items:start;gap:20px}.line-head.two,.sheet-line.two{grid-template-columns:minmax(0,1fr) 104px;gap:8px}.line-head{padding:8px 0;border-bottom:1px solid var(--line);color:var(--muted);text-transform:uppercase;font-size:.65rem;font-weight:800}.line-head span:last-child,.sheet-line strong{text-align:right}.sheet-line{padding:9px 0;border-bottom:1px solid #edf1f7;font-size:.75rem}.sheet-line span:nth-child(2){text-align:right;color:var(--muted);font-variant-numeric:tabular-nums}.subheading{margin-top:16px;color:#31588c;font-size:.7rem;font-weight:800;text-transform:uppercase}.empty-line{font-size:.75rem;color:var(--muted)}.section-total{display:flex;justify-content:space-between;gap:10px;margin-top:auto;padding-top:18px;font-size:.77rem;font-weight:800}.sheet-footer{display:flex;justify-content:flex-end;align-items:center;gap:24px;padding:16px 26px;background:#eaf2ff;border-top:1px solid var(--line)}.sheet-footer>div{display:flex;align-items:center;gap:12px}.sheet-footer span{font-size:.79rem;font-weight:800}.sheet-footer strong{font-size:.94rem}.sheet-footer .net-pay{border-left:1px solid #b7cbea;padding-left:24px}.sheet-footer .net-pay strong{font-size:1.35rem;color:#12458c}.source-block{padding:21px 26px;border-top:1px solid var(--line)}.source-block h4{margin:0 0 5px;font-size:.85rem}.source-block>p,.sheet-note{margin:0 0 12px;color:var(--muted);font-size:.73rem}.source-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;gap:22px;padding:9px 0;border-top:1px solid #edf1f7;font-size:.75rem}.source-row strong,.source-row small{display:block}.source-row small{margin-top:3px;color:var(--muted)}.sheet-note{padding:0 26px 18px}
@media(max-width:950px){.sheet-columns{grid-template-columns:1fr}.sheet-section{border-right:0;border-bottom:1px solid var(--line)}.sheet-section:last-child{border-bottom:0}}@media(max-width:600px){.sheet-head,.sheet-meta{padding:18px}.sheet-head{flex-direction:column}.sheet-period{text-align:left}.sheet-meta{grid-template-columns:1fr 1fr}.sheet-footer{flex-direction:column;align-items:flex-end;gap:8px}.sheet-footer .net-pay{border-left:0;padding-left:0}.source-row{grid-template-columns:1fr auto}.source-row span:last-child{grid-column:2}}
@media print{.payslip-sheet{border:0;border-radius:0;overflow:visible}.sheet-section{break-inside:avoid}.sheet-columns{display:block}}
</style>
